import { drizzle } from "drizzle-orm/durable-sqlite";
import { migrate } from "drizzle-orm/durable-sqlite/migrator";
import type { Db } from "./client.js";
import * as schema from "./schema/index.js";
// @ts-expect-error generated by drizzle-kit (plain JS bundling each .sql file as text)
import migrations from "../migrations/migrations.js";

/** Workers only: wraps Durable Object SQLite storage. Not exported from the package root. */
export function createDoDb(storage: DurableObjectStorage): Db {
  return drizzle(storage, { schema }) as unknown as Db;
}

/** Applies pending migrations (synchronous under the hood). Call inside `blockConcurrencyWhile`. */
export async function migrateDo(db: Db): Promise<void> {
  await migrate(db as unknown as Parameters<typeof migrate>[0], migrations);
}
